using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;
namespace Overclock {
 sealed class SensorView:UserControl {
  readonly SensorClient client;readonly DarkTree tree=new DarkTree{Dock=DockStyle.Fill,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.None,FullRowSelect=true,HideSelection=false,ItemHeight=30,ShowLines=false};readonly DataGridView table=Theme.Grid("Sensor","Current","Minimum","Maximum","Unit");readonly SensorGraph graph=new SensorGraph{Dock=DockStyle.Fill,BackColor=Theme.Surface};readonly Timer timer=new Timer{Interval=1000};readonly TextBox search=new DarkTextBox{Width=260,BackColor=Theme.Raised,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};readonly TableLayoutPanel panes=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1};bool updating;string filter="",shape="",selected;DateTime rendered;
  public SensorView(SensorClient c){client=c;Dock=DockStyle.Fill;BackColor=Theme.Background;var banner=new IdentityBanner{Caption="Sensors",Model="Real-time hardware sensors",Summary="Select hardware and a reading to explore current, minimum, maximum and history.",Height=142,ArtKey="sensors"};var toolbar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=54,Padding=new Padding(0,7,0,0)};var caption=Theme.Label("FILTER SENSORS",11);caption.Size=new Size(155,34);caption.TextAlign=ContentAlignment.MiddleLeft;toolbar.Controls.Add(caption);toolbar.Controls.Add(search);var reset=Theme.Button("Reset min / max");reset.Width=170;reset.Click+=(s,e)=>client.Reset();toolbar.Controls.Add(reset);panes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,22));panes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,45));panes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33));panes.RowStyles.Add(new RowStyle(SizeType.Percent,100));var hardware=new SectionPanel("Hardware tree"){Dock=DockStyle.Fill,Margin=new Padding(0,0,10,0)};var readings=new SectionPanel("Sensors"){Dock=DockStyle.Fill,Margin=new Padding(0,0,10,0)};var history=new SectionPanel("Selected sensor history"){Dock=DockStyle.Fill,Margin=Padding.Empty};hardware.Controls.Add(tree);readings.Controls.Add(table);history.Controls.Add(graph);panes.Controls.Add(hardware,0,0);panes.Controls.Add(readings,1,0);panes.Controls.Add(history,2,0);Controls.Add(panes);Controls.Add(toolbar);Controls.Add(banner);
   table.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None;table.Columns[0].Width=240;foreach(DataGridViewColumn col in table.Columns)if(col.Index>0)col.Width=100;table.Columns[4].Width=90;
   tree.AfterSelect+=(s,e)=>{filter=e.Node.Tag as string??"";rendered=DateTime.MinValue;RefreshData();};search.TextChanged+=(s,e)=>{rendered=DateTime.MinValue;RefreshData();};table.SelectionChanged+=(s,e)=>{if(updating||table.SelectedRows.Count==0)return;selected=table.SelectedRows[0].Tag as string;RefreshGraph();};timer.Tick+=(s,e)=>RefreshData();timer.Start();Disposed+=(s,e)=>timer.Dispose();RefreshData();
  }
  void RefreshData(){var snapshot=client.Snapshot;RefreshGraph();if(snapshot.Utc==rendered)return;rendered=snapshot.Utc;string signature=string.Join("|",snapshot.Sensors.Select(v=>v.Hardware+"/"+v.Type).Distinct().ToArray());if(shape!=signature){shape=signature;string old=tree.SelectedNode==null?"":tree.SelectedNode.Tag as string;tree.BeginUpdate();tree.Nodes.Clear();var all=tree.Nodes.Add("All hardware");all.Tag="";foreach(var group in snapshot.Sensors.GroupBy(s=>s.Hardware)){var root=tree.Nodes.Add(group.Key);root.ToolTipText=group.Key;root.Tag=group.Key+"|";foreach(string type in group.Select(s=>s.Type).Distinct()){var n=root.Nodes.Add(type);n.Tag=group.Key+"|"+type;}}tree.ExpandAll();tree.EndUpdate();}
   string[] parts=filter.Split('|');var rows=snapshot.Sensors.Where(v=>(filter==""||(v.Hardware==parts[0]&&(parts.Length<2||parts[1]==""||parts[1]==v.Type)))&&(search.Text==""||(v.Name+v.Hardware+v.Type).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0)).ToList();string chosen=selected;int scroll=table.FirstDisplayedScrollingRowIndex;updating=true;
   bool same=table.Rows.Count==rows.Count&&rows.Select((v,i)=>object.Equals(table.Rows[i].Tag,v.Id)).All(v=>v);if(!same){table.Rows.Clear();foreach(var v in rows){int i=table.Rows.Add(v.Name,F(v.Value),F(v.Min),F(v.Max),HardwareView.Unit(v.Type));table.Rows[i].Tag=v.Id;table.Rows[i].Cells[0].ToolTipText=v.Hardware+" · "+v.Name;}table.ClearSelection();}
   for(int i=0;i<rows.Count;i++){var v=rows[i];string[] values={v.Name,F(v.Value),F(v.Min),F(v.Max),HardwareView.Unit(v.Type)};for(int j=0;j<values.Length;j++)if(!object.Equals(table.Rows[i].Cells[j].Value,values[j]))table.Rows[i].Cells[j].Value=values[j];table.Rows[i].Cells[1].Style.ForeColor=v.Type=="Temperature"?Theme.Warning:v.Type=="Clock"||v.Type=="Load"?Theme.Mint:Theme.Text;if(v.Id==chosen)table.Rows[i].Selected=true;}
   if(rows.Count==0&&table.Rows.Count==0)table.Rows.Add(snapshot.Error??"No matching sensors","—","—","—","");selected=chosen;updating=false;if(scroll>=0&&scroll<table.Rows.Count)table.FirstDisplayedScrollingRowIndex=scroll;RefreshGraph();
  }
  static string F(float? v){return v.HasValue?v.Value.ToString("N1"):"—";}
  void RefreshGraph(){Queue<float> q;graph.Values=selected!=null&&client.History.TryGetValue(selected,out q)?q.ToArray():new float[0];var sensor=client.Snapshot.Sensors.FirstOrDefault(v=>v.Id==selected);graph.Title=sensor==null?"Select a sensor to explore its history":sensor.Name+"\nCurrent "+F(sensor.Value)+" "+HardwareView.Unit(sensor.Type)+"  ·  Min "+F(sensor.Min)+"  ·  Max "+F(sensor.Max);graph.Accent=sensor!=null&&sensor.Type=="Temperature"?Theme.Warning:Theme.Mint;graph.Invalidate();}
 }
 sealed class SensorGraph:Control {
  public string Title;public Color Accent=Theme.Accent;public float[] Values=new float[0];public SensorGraph(){DoubleBuffered=true;ForeColor=Theme.Text;BackColor=Theme.Surface;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;TextRenderer.DrawText(g,Title??"No history yet",Theme.Face(11),new Rectangle(14,10,Math.Max(1,Width-28),68),Theme.Text,TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis);int left=48,top=82,bottom=Height-34,right=Width-16;if(bottom<=top||right<=left)return;float max=Values.Length>0?Values.Max():100,min=Values.Length>0?Values.Min():0;if(max==min){max+=1;min=Math.Max(0,min-1);}float margin=(max-min)*.10f;max+=margin;min-=margin;for(int i=0;i<5;i++){float y=top+i*(bottom-top)/4f;using(var p=new Pen(Theme.Line))g.DrawLine(p,left,y,right,y);TextRenderer.DrawText(g,(max-i*(max-min)/4).ToString("0.#"),Theme.Face(9),new Rectangle(1,(int)y-9,left-5,22),Theme.Muted,TextFormatFlags.Right);}if(Values.Length<2){TextRenderer.DrawText(g,"Waiting for measured history",Theme.Face(11),new Rectangle(left,top+20,right-left,bottom-top),Theme.Muted,TextFormatFlags.WordBreak);return;}var points=Values.Select((v,i)=>new PointF(left+i*(right-left)/(float)(Values.Length-1),bottom-(v-min)/(max-min)*(bottom-top))).ToArray();using(var path=new GraphicsPath()){path.AddLines(points);path.AddLine(points[points.Length-1],new PointF(right,bottom));path.AddLine(new PointF(right,bottom),new PointF(left,bottom));path.CloseFigure();using(var b=new LinearGradientBrush(new Point(0,top),new Point(0,bottom),Color.FromArgb(95,Accent),Color.FromArgb(8,Accent)))g.FillPath(b,path);}using(var p=new Pen(Color.FromArgb(35,Accent),6))g.DrawLines(p,points);using(var p=new Pen(Accent,2))g.DrawLines(p,points);TextRenderer.DrawText(g,"Earlier samples",Theme.Face(9),new Point(left,Height-26),Theme.Muted);TextRenderer.DrawText(g,"Now",Theme.Face(9),new Point(Math.Max(left,right-32),Height-26),Theme.Muted);}
 }
}